/* ❌ Problemático */
.animate-element {
  left: 100px;
  top: 50px;
  width: 200px;
  transition: all 0.3s ease;
}

/* ✅ Otimizado */
.animate-element {
  transform: translate3d(100px, 50px, 0) scaleX(2);
  transition: transform 0.3s ease;
  will-change: transform;
}

// Throttling com requestAnimationFrame
let animationFrameId = null;

const updateAnimation = (timestamp) => {
  // Lógica de animação
  if (animationFrameId) {
    requestAnimationFrame(updateAnimation);
  }
};

// Iniciar animação
animationFrameId = requestAnimationFrame(updateAnimation);

// Parar quando não necessário
cancelAnimationFrame(animationFrameId);
animationFrameId = null;

/* Estilos de foco robustos */
.focus-visible {
  outline: 2px solid #005fcc;
  outline-offset: 2px;
  border-radius: 4px;
}

/* Skip links */
.skip-link {
  position: absolute;
  top: -40px;
  left: 6px;
  background: #000;
  color: #fff;
  padding: 8px;
  z-index: 1000;
  transition: top 0.3s;
}

.skip-link:focus {
  top: 6px;
}

/* Contraste responsivo */
@media (prefers-contrast: high) {
  .button {
    border: 2px solid currentColor;
    background: white;
    color: black;
  }
}

/* Fallback para texto de baixa importância */
.text-secondary {
  color: #64748b; /* Contraste 4.5:1 mínimo */
}

@media (prefers-contrast: less) {
  .text-secondary {
    color: #374151; /* Contraste melhorado */
  }
}

@media (prefers-reduced-motion: reduce) {
  .animate-on-scroll {
    animation: none;
    transition: none;
  }

  .loading-spinner {
    animation: none;
    /* Usar indicador estático */
  }
}

/* JavaScript detection */
if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
  document.body.classList.add('reduce-motion');
}

/* Mobile-first approach */
.card {
  padding: 16px;
  margin: 8px;
  font-size: 14px;
}

@media (min-width: 768px) {
  .card {
    padding: 24px;
    margin: 16px;
    font-size: 16px;
  }
}

@media (min-width: 1024px) {
  .card {
    padding: 32px;
    margin: 24px;
    font-size: 18px;
  }
}

.card-container {
  container-type: inline-size;
}

@container (min-width: 300px) {
  .card {
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: 1rem;
  }
}

@container (min-width: 500px) {
  .card {
    grid-template-columns: 1fr 1fr 1fr;
  }
}

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error('UI Error:', error, errorInfo);
    // Log to monitoring service
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="error-fallback">
          <h2>Algo deu errado</h2>
          <button onClick={() => window.location.reload()}>
            Tentar novamente
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const useAsyncOperation = (asyncFunction, dependencies = []) => {
  const [state, setState] = useState({
    loading: false,
    error: null,
    data: null
  });

  useEffect(() => {
    let isCancelled = false;

    const execute = async () => {
      setState(prev => ({ ...prev, loading: true, error: null }));

      try {
        // Timeout para evitar loading infinito
        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error('Timeout')), 10000)
        );

        const result = await Promise.race([asyncFunction(), timeoutPromise]);

        if (!isCancelled) {
          setState({ loading: false, error: null, data: result });
        }
      } catch (error) {
        if (!isCancelled) {
          setState({ loading: false, error, data: null });
        }
      }
    };

    execute();

    return () => {
      isCancelled = true;
    };
  }, dependencies);

  return state;
};

strategy.code_example:
class ResilientComponent extends React.Component {
  state = {
    hasError: false,
    retryCount: 0,
    lastError: null
  };

  handleRetry = () => {
    this.setState(prevState => ({
      hasError: false,
      retryCount: prevState.retryCount + 1,
      lastError: null
    }));
  };

  static getDerivedStateFromError(error) {
    return {
      hasError: true,
      lastError: error.message
    };
  }

  componentDidCatch(error, errorInfo) {
    console.error('Component error:', error, errorInfo);
    // Send to monitoring service
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="error-state">
          <h3>Algo deu errado</h3>
          <p>{this.state.lastError}</p>
          <button onClick={this.handleRetry}>
            Tentar novamente ({this.state.retryCount})
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}
